//! Zeroclaw route surface plugin.
//!
//! Publishes the Antigravity-facing model and CLI routing contract through
//! `PluginSchema` so the UI can render provider/model controls from D-Bus.
//!
//! Also writes the plugin-owned schema JSON to `/dev/shm/opdbus/schemas/zeroclaw.json`
//! so that the `op-grpc-bridge` Axum host can read it without duplicating the
//! schema definition.

use super::plugin_schema_defs::schema_from_state;
use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};
use std::path::Path;

const ZEROCLAW_SCHEMA_SHM_PATH: &str = "/dev/shm/opdbus/schemas/zeroclaw.json";

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ZeroclawState {
    pub status: String,
    pub selected_provider: String,
    pub selected_model: String,
    pub transport: Value,
    pub providers: Value,
    pub router: Value,
    pub model_routes: Value,
    pub tools: Value,
    pub config_schema: Value,
    pub ui_surfaces: Value,
    pub structured_output: Value,
}

pub struct ZeroclawPlugin;

impl Default for ZeroclawPlugin {
    fn default() -> Self {
        Self
    }
}

impl ZeroclawPlugin {
    pub fn new() -> Self {
        Self
    }

    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    /// Serialize the canonical zeroclaw schema to the plugin-owned tmpfs file.
    ///
    /// This is the only write path to `/dev/shm/opdbus/schemas/zeroclaw.json`;
    /// the `op-grpc-bridge` Axum host reads this file and never writes it.
    pub fn write_schema_file() -> Result<()> {
        Self::write_schema_file_to(ZEROCLAW_SCHEMA_SHM_PATH)
    }

    /// Serialize the canonical zeroclaw schema to a specific path.
    ///
    /// Used by tests and any caller that needs a hermetic output location.
    pub fn write_schema_file_to(path: impl AsRef<Path>) -> Result<()> {
        let schema = zeroclaw_schema();
        let json = serde_json::to_string(&schema)
            .map_err(|e| anyhow::anyhow!("failed to serialize zeroclaw schema to JSON: {}", e))?;

        let path = path.as_ref();
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| {
                anyhow::anyhow!(
                    "failed to create schema directory {}: {}",
                    parent.display(),
                    e
                )
            })?;
        }

        std::fs::write(path, json).map_err(|e| {
            anyhow::anyhow!(
                "failed to write zeroclaw schema to {}: {}",
                path.display(),
                e
            )
        })
    }

    pub(crate) fn current_state() -> ZeroclawState {
        // Decoupled from factory: local routing defaults to the on-box gemma4
        // via ollama. gemma4 is also the universal router (see `router` below).
        let selected_provider = Self::env_or("LLM_PROVIDER", "ollama");
        let selected_model = Self::env_or("LLM_MODEL", "gemma4");
        let router_endpoint = Self::env_or("ZEROCLAW_ROUTER_ENDPOINT", "http://localhost:11434");
        let wg_xray_target = Self::env_or("ZEROCLAW_WG_XRAY_TARGET", "wg-xray");
        let grpc_target = Self::env_or("ZEROCLAW_GRPC_TARGET", "http://10.200.0.1:50051");

        ZeroclawState {
            status: "declared".to_string(),
            selected_provider,
            selected_model,
            transport: json!({
                "dbus_object": "/opdbus/v1/plugins/zeroclaw",
                "grpc_target": grpc_target,
                "incus_container": wg_xray_target,
                "browser_surface": "gRPC-Web through op-web",
                "rest_aliases": ["/api/zeroclaw/chat", "/api/llm/chat"],
                // Canonical OSCAL/subid mapping authority — referenced, never copied.
                "policy_source": "/opdbus/v1/plugins/oscal_subid_registry",
            }),
            providers: json!([
                {"id": "factory", "route": "factory", "kind": "orchestrator", "aliases": ["default", "auto"]},
                {"id": "codex", "route": "openai-codex", "kind": "provider", "aliases": ["openai_codex", "codex"]},
                {"id": "ollama", "route": "ollama", "kind": "local", "aliases": ["gemma", "gemma4"]},
                {"id": "antigravity", "route": "antigravity", "kind": "orchestrator", "aliases": ["google.antigravity"]},
                {"id": "google", "route": "gemini", "kind": "provider", "aliases": ["gemini", "google-gemini"]},
                {"id": "opencode", "route": "custom:opencode", "kind": "cli", "aliases": []},
                {"id": "kilocode", "route": "custom:kilocode", "kind": "cli", "aliases": ["kilo-code", "kilo_code"]},
                {"id": "openrouter", "route": "openrouter", "kind": "router", "aliases": []},
                {"id": "anthropic", "route": "anthropic", "kind": "provider", "aliases": []},
                {"id": "openai", "route": "openai", "kind": "provider", "aliases": []},
                {"id": "gemini-cli", "route": "gemini-cli", "kind": "cli", "aliases": []},
                // OSCAL compliance routing: a policy-kind provider (assess, not chat).
                // `source` points at the canonical subid registry — the mapping
                // authority — instead of restating control mappings here.
                {"id": "oscal", "route": "oscal", "kind": "policy", "aliases": ["compliance", "subid", "nist"], "source": "/opdbus/v1/plugins/oscal_subid_registry"}
            ]),
            // gemma4 is the universal router: it classifies EVERY request into a
            // route/tag (provider+model, hint, candidate OSCAL subids). It only
            // emits tags — the deterministic layer (routes below, oscal registry,
            // xray) enforces them. Not just compliance routing.
            router: json!({
                "provider": "ollama",
                "model": "gemma4",
                "endpoint": router_endpoint,
                "scope": "all",
                "role": "context_aware_allocator",
                "emits": ["provider", "model", "hint", "candidate_subids", "confidence", "thinking_budget", "reasoning_effort"],
            }),
            model_routes: json!([
                {
                    "hint": "code",
                    "provider": "openrouter",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "gemini",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "ollama",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "gemma4 is the declared local classifier; unavailable until Ollama projects it.",
                    "api_key": null
                },
                // Factory auto-routing: selects best available provider based on query type
                {
                    "hint": "auto",
                    "provider": "factory",
                    "upstream_provider": "factory",
                    "transport": "auto",
                    "model": "auto",
                    "kind": "orchestrator",
                    "status": "declared",
                    "available": true,
                    "status_reason": "Factory auto-router available - selects best provider based on query classification.",
                    "api_key": null
                },
                {
                    "hint": "code",
                    "provider": "factory",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory code route -> openrouter/claude; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "factory",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory fast route -> gemini/flash; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "factory",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory local route -> ollama/gemma4; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "reasoning",
                    "provider": "factory",
                    "upstream_provider": "antigravity",
                    "transport": "direct",
                    "model": "gemini-3-pro-preview",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory reasoning route; Gemma dynamically allocates thinking budget.",
                    "api_key": null
                },
                // Compliance baseline routed through the OSCAL policy provider; the
                // model id is a canonical OSCAL profile reference resolved via the
                // subid registry, not an LLM model.
                {
                    "hint": "compliance",
                    "provider": "oscal",
                    "upstream_provider": "oscal",
                    "transport": "dbus",
                    "model": "NIST_SP_800-53_Rev5",
                    "kind": "policy",
                    "status": "declared",
                    "available": false,
                    "status_reason": "OSCAL policy provider is declared; unavailable until oscal_subid_registry is projected.",
                    "source": "/opdbus/v1/plugins/oscal_subid_registry",
                    "api_key": null
                }
            ]),
            tools: json!([
                {
                    "name": "zeroclaw.chat",
                    "description": "Send an Antigravity/Zeroclaw chat turn and return structured JSON when response_schema is present.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "message": {"type": "string"},
                            "provider": {"type": "string"},
                            "model": {"type": "string"},
                            "response_schema": {"type": "object"}
                        },
                        "required": ["message"]
                    }
                },
                {
                    "name": "zeroclaw.models.list",
                    "description": "List cached or live models for a Zeroclaw provider.",
                    "parameters": {
                        "type": "object",
                        "properties": {"provider": {"type": "string"}},
                        "required": []
                    }
                }
            ]),
            config_schema: json!({
                "source": "zeroclaw config schema",
                "schema_crate": "schemars",
                "native_type": "zeroclaw::config::schema::Config",
                "status": "available_via_cli_or_gateway"
            }),
            ui_surfaces: json!([
                {"path": "/chat", "name": "Antigravity Chat", "schema": "zeroclaw"},
                {"path": "/grpc", "name": "gRPC Diagnostics", "schema": "plugin-service"},
                {"path": "/models", "name": "Routable Models", "schema": "zeroclaw.providers"}
            ]),
            structured_output: json!({
                "sdk": "google.antigravity",
                "config_object": "LocalAgentConfig(response_schema=UiResponseSchema)",
                "extractor": "response.structured_output()",
                "response_schema": {
                    "action": "",
                    "metadata": {},
                    "confidence_score": 0.0
                },
                "pydantic_source": [
                    "import pydantic",
                    "class UiResponseSchema(pydantic.BaseModel):",
                    "    action: str",
                    "    metadata: dict[str, str]",
                    "    confidence_score: float"
                ],
                "ui_renderer": "JsonRenderer",
                "required": true
            }),
        }
    }
}

#[async_trait]
impl StatePlugin for ZeroclawPlugin {
    fn name(&self) -> &str {
        "zeroclaw"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(zeroclaw_schema())
    }

    async fn query_current_state(&self) -> Result<Value> {
        Self::write_schema_file()?;
        Ok(simd_json::serde::to_owned_value(Self::current_state())?)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-declared".to_string(),
                desired_hash: "schema-declared".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::current_state())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

pub(crate) fn zeroclaw_schema() -> PluginSchema {
    // The plugin IS the schema: derive directly from ZeroclawPlugin's live
    // state. Nothing is indexed here — adding a field to ZeroclawState is the
    // only way to change this schema.
    let state = simd_json::serde::to_owned_value(super::zeroclaw::ZeroclawPlugin::current_state())
        .unwrap_or_else(|_| json!({}));
    schema_from_state(
        "zeroclaw",
        "llm",
        "1.0.0",
        "Zeroclaw schema/RPC-native model router for Antigravity UI, CLI providers, and structured JSON output",
        &state,
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Read;

    #[test]
    fn should_write_zeroclaw_schema_to_shm() {
        // Use a temporary directory as the tmpfs root so the test is hermetic.
        let tmp = tempfile::tempdir().unwrap();
        let schema_path = tmp.path().join("opdbus/schemas/zeroclaw.json");

        ZeroclawPlugin::write_schema_file_to(&schema_path).unwrap();

        assert!(schema_path.exists());

        let mut buf = String::new();
        std::fs::File::open(&schema_path)
            .unwrap()
            .read_to_string(&mut buf)
            .unwrap();
        let round_tripped: PluginSchema = serde_json::from_str(&buf).unwrap();
        assert_eq!(round_tripped.name, "zeroclaw");
        assert_eq!(round_tripped.version, "1.0.0");
    }
}

//! Derive plugin schemas from `#[derive(schemars::JsonSchema)]` structs instead
//! of hand-building `FieldSchema` maps. This is the **standard** for new plugins
//! (see `docs/schema-from-structs.md`); existing plugins migrate as their config
//! structs get fully typed.
//!
//! The adapter walks the *JSON* of the derived schema rather than schemars'
//! typed API, so it stays robust across schemars 0.8/1.0 and decoupled — a
//! plugin only needs `serde_json::to_value(schemars::schema_for!(T))`.
//!
//! Before (hand-rolled, ~80 lines/plugin, drifts from the struct):
//! ```ignore
//! let mut socket_fields = HashMap::new();
//! socket_fields.insert("path".into(), FieldSchema { field_type: String, required: true, .. });
//! socket_fields.insert("port".into(), FieldSchema {
//!     field_type: Integer,
//!     constraints: vec![Constraint::Min{1.0}, Constraint::Max{65535.0}], .. });
//! PluginSchema::builder("unix_socket").array_field("sockets", Object(socket_fields), ..)
//! ```
//!
//! After (the struct *is* the schema):
//! ```ignore
//! #[derive(Serialize, Deserialize, schemars::JsonSchema)]
//! struct SocketEndpoint {
//!     /// doc comment → field description
//!     path: String,
//!     #[schemars(range(min = 1, max = 65535))] port: u16,
//!     ..
//! }
//! plugin_schema_from_json("unix_socket", "1.0.0", DESC,
//!     &serde_json::to_value(schemars::schema_for!(UnixSocketState)).unwrap())
//! ```

use op_state_store::{Constraint, FieldSchema, FieldType, PluginSchema};
use serde_json::{Map, Value as JVal};
use simd_json::OwnedValue;
use std::collections::{HashMap, HashSet};

/// Build a `PluginSchema` from the JSON of a schemars-derived schema.
///
/// The root type's top-level properties become the plugin's `fields`; `$ref`s
/// into `$defs`/`definitions` are resolved inline so nested structs (e.g. the
/// `SocketEndpoint` inside `sockets: Vec<SocketEndpoint>`) expand correctly.
pub fn plugin_schema_from_json(
    name: &str,
    version: &str,
    description: &str,
    root: &JVal,
) -> PluginSchema {
    let defs = root
        .get("$defs")
        .or_else(|| root.get("definitions"))
        .and_then(JVal::as_object);

    let top = resolve(root, defs);
    let required = required_set(top);

    let mut fields = HashMap::new();
    let mut subids = HashMap::new();
    if let Some(props) = top.get("properties").and_then(JVal::as_object) {
        for (fname, fnode) in props {
            let req = required.contains(fname.as_str());
            fields.insert(fname.clone(), field_schema(fnode, defs, req));
            if let Some(subid) = fnode.get("x-oscal-subid").and_then(JVal::as_str) {
                subids.insert(fname.clone(), subid.to_string());
            }
        }
    }

    // Root-level `#[schemars(extend("x-oscal-subid" = ...))]` → reserved key.
    if let Some(subid) = root.get("x-oscal-subid").and_then(JVal::as_str) {
        subids.insert("__schema__".to_string(), subid.to_string());
    }

    let mut schema = PluginSchema::builder(name)
        .version(version)
        .description(description)
        .build();
    schema.fields = fields;
    schema.subids = subids;
    // Struct-level `#[schemars(extend("x-immutable-paths" = [...]))]` → immutable_paths.
    if let Some(paths) = root.get("x-immutable-paths").and_then(JVal::as_array) {
        schema.immutable_paths = paths
            .iter()
            .filter_map(|v| v.as_str().map(String::from))
            .collect();
    }
    schema
}

/// Follow a single `$ref` into `$defs`/`definitions`, recursively.
fn resolve<'a>(node: &'a JVal, defs: Option<&'a Map<String, JVal>>) -> &'a JVal {
    if let (Some(r), Some(d)) = (node.get("$ref").and_then(JVal::as_str), defs) {
        if let Some(key) = r.rsplit('/').next() {
            if let Some(target) = d.get(key) {
                return resolve(target, defs);
            }
        }
    }
    node
}

fn required_set(node: &JVal) -> HashSet<String> {
    node.get("required")
        .and_then(JVal::as_array)
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect()
        })
        .unwrap_or_default()
}

fn field_type(node: &JVal, defs: Option<&Map<String, JVal>>) -> FieldType {
    let node = resolve(node, defs);

    // For `Option<T>` where T is a non-primitive schema, schemars emits an
    // `anyOf`/`oneOf` with the referenced schema and a `null` alternative. Walk
    // the first non-null alternative so we still produce a concrete type.
    if let Some(alternatives) = node
        .get("anyOf")
        .or_else(|| node.get("oneOf"))
        .and_then(JVal::as_array)
    {
        if let Some(non_null) = alternatives.iter().find(|a| type_str(a) != Some("null")) {
            return field_type(non_null, defs);
        }
    }

    if let Some(en) = node.get("enum").and_then(JVal::as_array) {
        return FieldType::Enum(
            en.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect(),
        );
    }

    match type_str(node) {
        Some("string") => FieldType::String,
        Some("integer") => FieldType::Integer,
        Some("number") => FieldType::Float,
        Some("boolean") => FieldType::Boolean,
        Some("array") => {
            let item = node
                .get("items")
                .map(|i| field_type(i, defs))
                .unwrap_or(FieldType::Any);
            FieldType::Array(Box::new(item))
        }
        Some("object") => {
            let req = required_set(node);
            let mut m = HashMap::new();
            if let Some(props) = node.get("properties").and_then(JVal::as_object) {
                for (k, v) in props {
                    m.insert(k.clone(), field_schema(v, defs, req.contains(k.as_str())));
                }
            }
            FieldType::Object(m)
        }
        _ => FieldType::Any,
    }
}

/// schemars emits `"type": "string"` or, for `Option<T>`, `"type": ["string","null"]`.
/// Collapse to the first non-null type.
fn type_str(node: &JVal) -> Option<&str> {
    match node.get("type") {
        Some(JVal::String(s)) => Some(s.as_str()),
        Some(JVal::Array(a)) => a.iter().filter_map(JVal::as_str).find(|t| *t != "null"),
        _ => None,
    }
}

fn field_schema(node: &JVal, defs: Option<&Map<String, JVal>>, required: bool) -> FieldSchema {
    // Metadata such as `description`, `examples`, `readOnly`, and `default` are
    // declared on the field node itself; only the type/reference needs to be
    // resolved through `$defs`.
    let meta = node;
    FieldSchema {
        field_type: field_type(node, defs),
        required,
        description: meta
            .get("description")
            .and_then(JVal::as_str)
            .unwrap_or_default()
            .to_string(),
        default: meta.get("default").map(to_simd),
        example: example_of(meta).map(to_simd),
        constraints: constraints(meta),
        read_only: meta
            .get("readOnly")
            .and_then(JVal::as_bool)
            .unwrap_or(false),
        read_only_when: None,
    }
}

fn example_of(node: &JVal) -> Option<&JVal> {
    if let Some(first) = node
        .get("examples")
        .and_then(JVal::as_array)
        .and_then(|a| a.first())
    {
        return Some(first);
    }
    node.get("example")
}

fn constraints(node: &JVal) -> Vec<Constraint> {
    let mut out = Vec::new();
    if let Some(m) = node.get("minimum").and_then(JVal::as_f64) {
        out.push(Constraint::Min { value: m });
    }
    if let Some(m) = node.get("maximum").and_then(JVal::as_f64) {
        out.push(Constraint::Max { value: m });
    }
    if let Some(p) = node.get("pattern").and_then(JVal::as_str) {
        out.push(Constraint::Pattern {
            regex: p.to_string(),
        });
    }
    out
}

/// `serde_json::Value` → `simd_json::OwnedValue` (the `Value` op_state_store uses).
fn to_simd(v: &JVal) -> OwnedValue {
    let mut bytes = serde_json::to_vec(v).unwrap_or_default();
    simd_json::to_owned_value(&mut bytes).unwrap_or_else(|_| simd_json::json!(null))
}

/// Test-only **full-fidelity** diff: lists every way `derived` departs from the
/// golden hand-rolled `reference` — field set, recursive types, `required`,
/// descriptions, defaults, examples, constraints, `read_only`, immutable paths,
/// and OSCAL subids at every nesting level.
/// Empty result ⇒ the derived schema reproduces the reference exactly. Any entry
/// must be consciously resolved (annotate the struct to preserve it, or document
/// it as a deliberate correction of a hand-rolled bug).
#[cfg(test)]
pub(crate) fn schema_diffs(reference: &PluginSchema, derived: &PluginSchema) -> Vec<String> {
    let mut d = Vec::new();
    if reference.name != derived.name {
        d.push(format!("name: {:?} -> {:?}", reference.name, derived.name));
    }
    if reference.version != derived.version {
        d.push(format!(
            "version: {:?} -> {:?}",
            reference.version, derived.version
        ));
    }
    if reference.description != derived.description {
        d.push(format!(
            "description: {:?} -> {:?}",
            reference.description, derived.description
        ));
    }
    let (mut ir, mut id) = (
        reference.immutable_paths.clone(),
        derived.immutable_paths.clone(),
    );
    ir.sort();
    id.sort();
    if ir != id {
        d.push(format!("immutable_paths: {ir:?} -> {id:?}"));
    }
    if reference.subids != derived.subids {
        d.push(format!(
            "subids: {:?} -> {:?}",
            reference.subids, derived.subids
        ));
    }
    let keys: std::collections::BTreeSet<&String> = reference
        .fields
        .keys()
        .chain(derived.fields.keys())
        .collect();
    for k in keys {
        match (reference.fields.get(k), derived.fields.get(k)) {
            (Some(r), Some(v)) => field_diffs(&mut d, k, r, v),
            (Some(_), None) => d.push(format!("{k}: DROPPED (in reference, not derived)")),
            (None, Some(_)) => d.push(format!("{k}: ADDED (in derived, not reference)")),
            (None, None) => {}
        }
    }
    d
}

#[cfg(test)]
fn field_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldSchema, v: &FieldSchema) {
    if type_tag(&r.field_type) != type_tag(&v.field_type) {
        d.push(format!(
            "{prefix}.type: {} -> {}",
            type_tag(&r.field_type),
            type_tag(&v.field_type)
        ));
    }
    if r.required != v.required {
        d.push(format!(
            "{prefix}.required: {} -> {}",
            r.required, v.required
        ));
    }
    if r.description != v.description {
        d.push(format!(
            "{prefix}.description: {:?} -> {:?}",
            r.description, v.description
        ));
    }
    if val_str(&r.default) != val_str(&v.default) {
        d.push(format!(
            "{prefix}.default: {} -> {}",
            val_str(&r.default),
            val_str(&v.default)
        ));
    }
    if val_str(&r.example) != val_str(&v.example) {
        d.push(format!(
            "{prefix}.example: {} -> {}",
            val_str(&r.example),
            val_str(&v.example)
        ));
    }
    if constraint_tags(&r.constraints) != constraint_tags(&v.constraints) {
        d.push(format!(
            "{prefix}.constraints: {:?} -> {:?}",
            constraint_tags(&r.constraints),
            constraint_tags(&v.constraints)
        ));
    }
    if r.read_only != v.read_only {
        d.push(format!(
            "{prefix}.read_only: {} -> {}",
            r.read_only, v.read_only
        ));
    }

    // Recurse into nested container types so nested field-level diffs are reported.
    field_type_diffs(d, prefix, &r.field_type, &v.field_type);
}

#[cfg(test)]
fn field_type_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldType, v: &FieldType) {
    match (r, v) {
        (FieldType::Array(r_inner), FieldType::Array(v_inner)) => {
            field_type_diffs(d, &format!("{prefix}[]"), r_inner, v_inner);
        }
        (FieldType::Object(r_map), FieldType::Object(v_map)) => {
            let keys: std::collections::BTreeSet<&String> =
                r_map.keys().chain(v_map.keys()).collect();
            for k in keys {
                match (r_map.get(k), v_map.get(k)) {
                    (Some(rf), Some(vf)) => field_diffs(d, &format!("{prefix}.{k}"), rf, vf),
                    (Some(_), None) => {
                        d.push(format!("{prefix}.{k}: DROPPED (in reference, not derived)"))
                    }
                    (None, Some(_)) => {
                        d.push(format!("{prefix}.{k}: ADDED (in derived, not reference)"))
                    }
                    (None, None) => {}
                }
            }
        }
        _ => {}
    }
}

#[cfg(test)]
fn val_str(v: &Option<OwnedValue>) -> String {
    match v {
        Some(x) => format!("{x:?}"),
        None => "∅".into(),
    }
}

#[cfg(test)]
fn type_tag(t: &FieldType) -> String {
    match t {
        FieldType::String => "string".into(),
        FieldType::Integer => "integer".into(),
        FieldType::Float => "float".into(),
        FieldType::Boolean => "boolean".into(),
        FieldType::Any => "any".into(),
        FieldType::Enum(_) => "enum".into(),
        FieldType::Array(i) => format!("array<{}>", type_tag(i)),
        FieldType::Object(m) => {
            let mut entries: Vec<String> = m
                .iter()
                .map(|(k, v)| format!("{k}:{}", type_tag(&v.field_type)))
                .collect();
            entries.sort();
            format!("object{{{}}}", entries.join(","))
        }
    }
}

#[cfg(test)]
fn constraint_tags(cs: &[Constraint]) -> Vec<String> {
    let mut v: Vec<String> = cs
        .iter()
        .map(|c| match c {
            Constraint::Min { value } => format!("min:{value}"),
            Constraint::Max { value } => format!("max:{value}"),
            Constraint::Pattern { regex } => format!("pattern:{regex}"),
            Constraint::OneOf { .. } => "oneof".into(),
            Constraint::RequiresField { field } => format!("requires:{field}"),
            Constraint::Custom { validator } => format!("custom:{validator}"),
        })
        .collect();
    v.sort();
    v
}

