                "type": "object",
                "properties": {
                    "wrapper": {
                        "type": "object",
                        "properties": {
                            "inner": { "type": "string", "description": "inner field" }
                        },
                        "required": ["inner"]
                    }
                },
                "required": ["wrapper"]
            }),
        );
        let derived = plugin_schema_from_json(
            "nested_test",
            "1.0.0",
            "desc",
            &serde_json::json!({
                "type": "object",
                "properties": {
                    "wrapper": {
                        "type": "object",
                        "properties": {
                            "inner": { "type": "integer", "description": "inner field" }
                        },
