    use op_state_store::{FieldSchema, FieldType, PluginSchema};
    use serde_json::Value as JVal;
    use simd_json::OwnedValue;

    /// Build a golden `PluginSchema` from a default state value and its schemars
    /// schema JSON.
    ///
    /// `schema_from_state` produces examples and no descriptions; the derived
    /// schemars schema produces defaults and descriptions. This helper bridges
    /// the two by moving examples to defaults and copying descriptions/subids
    /// from the schemars JSON, so the golden matches the derived schema exactly.
    pub fn golden_from_state_and_schema(
        state: &OwnedValue,
        schema_json: &JVal,
        name: &str,
        category: &str,
        version: &str,
        description: &str,
    ) -> PluginSchema {
        let mut plugin_schema =
            schema_from_state(name, category, version, description, state);

        // Move schema_from_state examples into defaults so they match the
        // schemars-derived defaults.
        for field in plugin_schema.fields.values_mut() {
            move_example_to_default(field);
        }

        // Apply descriptions from the schemars schema JSON.
        if let Some(props) = schema_json.get("properties").and_then(|p| p.as_object()) {
            for (fname, fschema) in plugin_schema.fields.iter_mut() {
                if let Some(schemars_field) = props.get(fname) {
                    apply_description(fschema, schemars_field);
                }
            }
        }

        // Collect root and top-level subids from the schemars schema.
        if let Some(subid) = schema_json.get("x-oscal-subid").and_then(|s| s.as_str()) {
            plugin_schema
                .subids
                .insert("__schema__".to_string(), subid.to_string());
        }
        if let Some(props) = schema_json.get("properties").and_then(|p| p.as_object()) {
            for (fname, fnode) in props {
                if let Some(subid) = fnode.get("x-oscal-subid").and_then(|s| s.as_str()) {
                    plugin_schema
                        .subids
                        .insert(fname.clone(), subid.to_string());
                }
            }
        }

        plugin_schema
    }

    fn move_example_to_default(field: &mut FieldSchema) {
        if field.example.is_some() {
            field.default = field.example.clone();
            field.example = None;
        }
        move_example_to_default_in_field_type(&mut field.field_type);
    }

    fn move_example_to_default_in_field_type(field_type: &mut FieldType) {
        match field_type {
            FieldType::Object(map) => {
                for f in map.values_mut() {
                    move_example_to_default(f);
                }
            }
            FieldType::Array(inner) => {
                move_example_to_default_in_field_type(inner);
            }
            _ => {}
        }
    }

    fn apply_description(field: &mut FieldSchema, schemars_node: &JVal) {
        if let Some(desc) = schemars_node.get("description").and_then(|d| d.as_str()) {
            field.description = desc.to_string();
        }
        apply_description_to_field_type(&mut field.field_type, schemars_node);
    }

    fn apply_description_to_field_type(field_type: &mut FieldType, schemars_node: &JVal) {
        match field_type {
            FieldType::Object(map) => {
                if let Some(props) =
                    schemars_node.get("properties").and_then(|p| p.as_object())
                {
                    for (k, v) in map.iter_mut() {
                        if let Some(snode) = props.get(k) {
                            apply_description(v, snode);
                        }
                    }
                }
            }
            FieldType::Array(inner) => {
                if let Some(items) = schemars_node.get("items") {
                    apply_description_to_field_type(inner, items);
                }
            }
            _ => {}
        }
    }
}

